/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (21,'SoundMaster Pro X Wireless Over-Ear Headphones','<p><span>&lt;p&gt;Experience studio-quality audio with the &lt;strong&gt;SoundMaster Pro X&lt;/strong&gt;. Featuring hybrid active noise cancellation (ANC), custom 40mm drivers, and up to 60 hours of continuous playtime.&lt;/p&gt;&lt;p&gt;Designed with premium memory foam earcups for all-day ergonomic comfort.&lt;/p&gt;</span></p>','ITM-SMPX-001',37,3,1,'\"[\\\"Hybrid Active Noise Cancellation up to 45dB\\\",\\\"Multipoint Connection (Pair 2 devices simultaneously)\\\",\\\"Foldable design with premium hard-shell travel case included\\\",\\\"Ultra-fast charging: 10 mins charge = 5 hours playtime\\\",\\\"Built-in quad microphone array for crystal clear calls\\\"]\"','\"[{\\\"key\\\":\\\"Driver Size\\\",\\\"value\\\":\\\"40mm Dynamic Neodymium\\\"},{\\\"key\\\":\\\"Connectivity\\\",\\\"value\\\":\\\"Bluetooth 5.3 & 3.5mm Audio Jack\\\"},{\\\"key\\\":\\\"Battery Life\\\",\\\"value\\\":\\\"Up to 60 Hours (ANC Off) / 40 Hours (ANC On)\\\"},{\\\"key\\\":\\\"Weight\\\",\\\"value\\\":\\\"256 grams\\\"},{\\\"key\\\":\\\"Warranty\\\",\\\"value\\\":\\\"2 Years Manufacturer Warranty\\\"}]\"','/storage/products/000000000000046.png','\"[\\\"/storage/products/000000000000047.png\\\",\\\"/storage/products/000000000000048.png\\\",\\\"/storage/products/000000000000049.png\\\",\\\"/storage/products/000000000000050.png\\\",\\\"/storage/products/000000000000051.png\\\",\\\"/storage/products/000000000000052.png\\\"]\"',0,'2026-08-06 10:40:43','2026-08-13 13:30:39'),(22,'PulseTech Smart Fitness Watch Series 7','<div><div><span>&lt;p&gt;Stay connected and monitor your health with the &lt;strong&gt;PulseTech Smart Watch Series 7&lt;/strong&gt;. Features an Always-On AMOLED Display, SpO2 sensor, continuous heart rate tracking, and 100+ workout modes.&lt;/p&gt;</span></div></div>','ITM-PTSW-007',37,3,1,'\"[\\\"Dual-frequency standalone GPS tracking\\\",\\\"24/7 Heart rate, sleep stage, and stress monitoring\\\"